/**
 * Routes the player to ents called on world 444, oldest first, with the Shortest Path plugin.
 * {@link RelayClient} receives the calls, {@link EntTracker} turns sightings into ents, and this
 * class picks the target, hands it to Shortest Path and notices arrival.
 * <p>
 * Everything but the relay connection runs on the client thread, which is also where the overlay
 * renders and Shortest Path reads its messages, so none of the state needs locking.
 */
@Slf4j
@Singleton
public class EntPathfinder
{
	/** The community forestry world, and the only world the feature connects on. */
	private static final int FORESTRY_WORLD = 444;

	/** Wider than Shortest Path's own default of 5, so the path moves on before it clears itself. */
	private static final int ARRIVAL_TILES = 7;

	/**
	 * How long the relay connection outlives leaving the world, so hops, breaks and relogs reuse one
	 * connection. An idle connection costs the relay nothing; each new one counts against its quota.
	 */
	private static final long DISCONNECT_GRACE_MILLIS = 10 * 60_000;

	private static final String ENT = "ENT";
	private static final String SHORTEST_PATH = "shortestpath";

	private static final String ENT_DONE = "d(?:ead|one)?[0-5]?|doa|fake";

	private static final Pattern ENT_COMPLETED_PATTERN = Pattern.compile(
		"^(?:(?<before>.+?)\\s+(?:" + ENT_DONE + ")"
			+ "|(?:" + ENT_DONE + ")\\s+(?<after>.+))$",
		Pattern.CASE_INSENSITIVE);

	private static final String ENT_SUFFIX = "(?:\\s+(?:p|plugin|l|late|again|solo|duo|stall|spam))?";

	private static final Pattern ENT_CALL_REGEX = Pattern.compile(
		"^(?!.*\\b(?:" + ENT_DONE + ")\\b)"
			+ "(?:(?<before>.+?)\\s+ents?" + ENT_SUFFIX
			+ "|ents?\\s+(?<after>.+?)" + ENT_SUFFIX + ")$",
		Pattern.CASE_INSENSITIVE);

	private static final Duration CALL_COOLDOWN = Duration.ofSeconds(10);

	// Last call time for each username (primarily to avoid spam by using CALL_COOLDOWN)
	private final Map<String, Instant> lastCallTimes = new HashMap<>();

	private final ScoutingConfig config;
	private final EntPathfinderOverlay overlay;

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private EventBus eventBus;

	@Inject
	private OkHttpClient okHttpClient;

	@Inject
	private Gson gson;

	@Inject
	private Notifier notifier;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private ItemManager itemManager;

	@Inject
	private WorldMapPointManager worldMapPointManager;

	/** Used instead of {@code @Schedule}, which stalls while the client is minimised. */
	@Inject
	private ScheduledExecutorService executor;

	@Inject
	@Named("developerMode")
	private boolean developerMode;

	private volatile RelayClient relay;
	private volatile boolean running;
	private ScheduledFuture<?> connectionTask;
	private long lastNeededRelayMillis;

	// Client thread only.
	private final EntTracker tracker = new EntTracker();
	/** Running ents not yet reached, oldest first. The path points at the first. */
	private List<Ent> live = Collections.emptyList();
	/** The target we last asked Shortest Path to show, or null if we have no path. */
	private WorldPoint ourTarget;
	/** Only the latest Shortest Path query is kept, so one that never replies can't pile up callbacks. */
	private String pendingQueryId;
	private Consumer<List<?>> pendingQuery;
	/** The last point we pointed the hint arrow at, to tell our arrow from another source's. */
	private WorldPoint arrowPoint;
	/** The world map marker for the current target, and the point it sits on. */
	private WorldMapPoint mapPoint;
	private WorldPoint mapTarget;
	/** When the player logged in on the forestry world, by the relay's clock; 0 while not logged in there. */
	private long loggedInSince;

	@Inject
	EntPathfinder(ScoutingPlugin plugin, ScoutingConfig config)
	{
		this.config = config;
		// Built here rather than injected, so Guice never has to resolve a cycle between the two.
		this.overlay = new EntPathfinderOverlay(plugin, this, config);
	}

	/** Switch the feature on or off. Safe to repeat. */
	public synchronized void setEnabled(boolean enabled)
	{
		if (enabled && !running)
		{
			start();
		}
		else if (!enabled && running)
		{
			stop();
		}
	}

	private void start()
	{
		relay = new RelayClient(okHttpClient, gson, executor, calls -> clientThread.invokeLater(() -> receive(calls)));
		eventBus.register(this);
		overlayManager.add(overlay);
		running = true;
		connectionTask = executor.scheduleWithFixedDelay(this::updateRelayConnection, 1, 1, TimeUnit.SECONDS);

		// Switched on mid-session, ents count from now: the actual login time is not known.
		clientThread.invoke(() -> loggedInSince = isLoggedInOnForestryWorld() ? serverNow() : 0);
	}

	private void stop()
	{
		running = false;
		connectionTask.cancel(false);
		relay.close();
		eventBus.unregister(this);
		overlayManager.remove(overlay);

		// The state, and Shortest Path, belong to the client thread.
		clientThread.invoke(() ->
		{
			for (Ent ent : live)
			{
				overlay.removeSkipEntry(ent);
			}
			tracker.reset();
			live = Collections.emptyList();
			loggedInSince = 0;
			lastCallTimes.clear();
			// We're unregistered, so a query could never be answered. Clear only if we set a path.
			if (ourTarget != null)
			{
				eventBus.post(new PluginMessage(SHORTEST_PATH, "clear", Collections.emptyMap()));
			}
			ourTarget = null;
			pendingQuery = null;
			pendingQueryId = null;
			clearHintArrow();
			clearMapPoint();
		});
	}

	public void onPathSettingChanged()
	{
		clientThread.invoke(() ->
		{
			if (!config.entPathfinderEnabled())
			{
				clearPath();
			}
			else if (!live.isEmpty())
			{
				pathTo(live.get(0));
			}
		});
	}

	public void onHintArrowSettingChanged()
	{
		clientThread.invoke(() ->
		{
			if (config.entShowHintArrow())
			{
				updateHintArrow();
			}
			else
			{
				clearHintArrow();
			}
		});
	}

	/** Every second, on the executor: hold a relay connection only while on the forestry world. */
	private void updateRelayConnection()
	{
		// Catches everything, since one uncaught throw would cancel this task for the session.
		try
		{
			long now = System.currentTimeMillis();
			GameState state = client.getGameState();
			// Loading screens and brief disconnects count, or every region load would reconnect.
			boolean inGame = state == GameState.LOGGED_IN || state == GameState.LOADING || state == GameState.CONNECTION_LOST;

			if (inGame && client.getWorld() == FORESTRY_WORLD)
			{
				lastNeededRelayMillis = now;
				relay.connect(config.entRelayUrl().trim() + "?world=" + FORESTRY_WORLD);
			}
			else if (now - lastNeededRelayMillis > DISCONNECT_GRACE_MILLIS)
			{
				relay.disconnect();
			}
		}
		catch (Throwable t)
		{
			log.warn("Ent relay connection check failed", t);
		}
	}

	private void receive(List<Call> calls)
	{
		if (!running)
		{
			return;
		}

		// The relay only sends ents; this guards against a misconfigured one.
		List<Call> entCalls = calls.stream().filter(c -> ENT.equals(c.getEventType())).collect(Collectors.toList());

		long now = serverNow();
		for (Ent ent : tracker.accept(entCalls, now))
		{
			if (isEligible(ent) && !isIgnored(ent))
			{
				notifier.notify(config.entNotify(), "Ent called: " + ent.getLabel() + " (" + ent.secondsRemaining(now) + "s left)");
			}
		}
		refresh();
	}

	/** A region load or a brief disconnect is not a new login; logging out or hopping away is. */
	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (isLoggedInOnForestryWorld())
		{
			if (loggedInSince == 0)
			{
				loggedInSince = serverNow();
			}
		}
		else if (event.getGameState() == GameState.LOGIN_SCREEN || event.getGameState() == GameState.HOPPING)
		{
			loggedInSince = 0;
		}
	}

	@Subscribe
	public void onGameTick(GameTick tick)
	{
		refresh();

		// Measured here because Shortest Path reports nothing about progress.
		if (!live.isEmpty() && isReached(live.get(0)))
		{
			live.get(0).setReached(true);
			refresh();
		}
	}

	// Developer mode only: {@code ::mockcall message}
	@Subscribe
	public void onCommandExecuted(CommandExecuted event)
	{
		if (!developerMode || !"mockcall".equals(event.getCommand()) || !isLoggedInOnForestryWorld())
		{
			return;
		}

		ChatMessage chatMessage = new ChatMessage();
		chatMessage.setType(ChatMessageType.FRIENDSCHAT);
		chatMessage.setName("mockcall");
		chatMessage.setMessage(String.join(" ", event.getArguments()));

		onChatMessage(chatMessage);
	}

	@Subscribe
	public void onChatMessage(ChatMessage chatMessage)
	{
		if (chatMessage.getType() != ChatMessageType.FRIENDSCHAT || !isLoggedInOnForestryWorld())
		{
			return;
		}

		String message = chatMessage.getMessage().trim().toLowerCase(Locale.ROOT);;

		if (config.entChatRemoveEnabled())
		{
			Matcher matcher = ENT_COMPLETED_PATTERN.matcher(message);
			if (matcher.matches())
			{
				String name = matcher.group("before") != null ? matcher.group("before") : matcher.group("after");
				Set<CallLocation> locations = CallLocationFinder.find(name);
				if (!locations.isEmpty())
				{
					tracker.getActive(serverNow()).forEach(ent ->
					{
						if (locations.contains(ent.getLocation()))
						{
							ent.setReached(true);
						}
					});
					// onChatMessage runs during a client script callback. Defer the call because
                    // CallLocation#isUnlocked invokes client.runScript, which is not reentrant.
					clientThread.invokeLater(this::refresh);
				}
			}
		}

		if (config.entChatAddEnabled())
		{
			Matcher matcher = ENT_CALL_REGEX.matcher(message);
			if (matcher.matches())
			{
				String caller = Text.sanitize(chatMessage.getName());
				Instant now = Instant.now();
				Instant last = lastCallTimes.get(caller);

				if (last != null && Duration.between(last, now).compareTo(CALL_COOLDOWN) < 0)
				{
					return;
				}
				lastCallTimes.put(caller, now);

				String name = matcher.group("before") != null ? matcher.group("before") : matcher.group("after");
				if (developerMode && "unnamed".equals(name))
				{
					createCall(null);
				}
				else
				{
					CallLocationFinder.find(name).stream().findFirst().ifPresent(this::createCall);
				}
			}
		}
	}

	private void createCall(CallLocation location)
	{
		// location is null only for the developer-mode "unnamed" test call,
		// which uses fixed coordinates in the Kharazi Jungle
		int x = location != null ? location.getCentreX() : 2840;
		int y = location != null ? location.getCentreY() : 2910;

		String json = String.format(
			"{\"event_type\":\"%s\",\"world\":%d,\"x_coord\":%d,\"y_coord\":%d,\"plane\":0,\"discovered_time\":%d}",
			ENT, FORESTRY_WORLD, x, y, serverNow());
		Call call = gson.fromJson(json, Call.class);

		// onChatMessage runs during a client script callback. Defer the call because
		// CallLocation#isUnlocked invokes client.runScript, which is not reentrant.
		clientThread.invokeLater(() -> receive(Collections.singletonList(call)));
	}

	/**
	 * Handles Shortest Path's reply to a {@link #queryPath} request. Replies are broadcast to every
	 * plugin, so the request id is checked to make sure this one answers our latest query. Runs the
	 * saved callback with the reported target list, or null if no path is set.
	 */
	@Subscribe
	public void onPluginMessage(PluginMessage message)
	{
		if (!SHORTEST_PATH.equals(message.getNamespace()) || !"currentTarget".equals(message.getName()))
		{
			return;
		}

		Map<String, Object> data = message.getData();
		if (pendingQuery == null || !Objects.equals(pendingQueryId, data.get("id")))
		{
			return; // not our query, or superseded by a newer one
		}

		Consumer<List<?>> callback = pendingQuery;
		pendingQuery = null;
		pendingQueryId = null;

		boolean set = Boolean.TRUE.equals(data.get("set"));
		callback.accept(set ? (List<?>) data.get("target") : null);
	}

	/**
	 * Rebuild the list and point the path at its first entry: the oldest ent not yet reached, and
	 * the closest to ending. Filtering here rather than in the tracker lets a late report still find
	 * its ent, and makes an island setting apply at once.
	 */
	private void refresh()
	{
		List<Ent> previous = live;
		live = tracker.getActive(serverNow()).stream()
			.filter(e -> !e.isReached() && isEligible(e) && !isIgnored(e))
			.collect(Collectors.toList());

		for (Ent ent : previous)
		{
			if (!live.contains(ent))
			{
				overlay.removeSkipEntry(ent);
			}
		}

		for (Ent ent : live)
		{
			if (!previous.contains(ent))
			{
				overlay.addSkipEntry(ent);
			}
		}

		// The centre drifts as sightings arrive.
		updateMapPoint();
		if (config.entShowHintArrow())
		{
			updateHintArrow();
		}

		if (!config.entPathfinderEnabled())
		{
			return;
		}

		Ent next = live.isEmpty() ? null : live.get(0);

		if (!previous.isEmpty() && previous.get(0) == next)
		{
			return;
		}

		if (next == null)
		{
			clearPath();
		}
		else
		{
			pathTo(next);
		}
	}

	/** Drop ent from the list and move on to the next ent. */
	void skip(Ent ent)
	{
		ent.setReached(true);
		refresh();
	}

	/** Only an ent that spawned while the player was logged in on the world can reward them. */
	private boolean isEligible(Ent ent)
	{
		return loggedInSince > 0 && ent.getFirstSeen() >= loggedInSince;
	}

	private boolean isLoggedInOnForestryWorld()
	{
		return client.getGameState() == GameState.LOGGED_IN && client.getWorld() == FORESTRY_WORLD;
	}

	private boolean isIgnored(Ent ent)
	{
		CallLocation location = ent.getLocation();
		return location != null
			&& ((config.entIgnoreSunbleak() && location == CallLocation.SUNBLEAK)
			|| (config.entIgnoreDrumstickIsle() && location == CallLocation.DRUMSTICK)
			|| (config.entIgnoreQuestLocked() && !location.isUnlocked(client)));
	}

	/**
	 * Asks Shortest Path what path it is currently showing. The answer arrives later, in
	 * {@link #onPluginMessage}, which runs {@code callback} with the target list (null if no path is
	 * set). Only the latest query is kept: a newer call replaces an older one that never got a reply.
	 */
	private void queryPath(Consumer<List<?>> callback)
	{
		pendingQueryId = UUID.randomUUID().toString();
		pendingQuery = callback;
		eventBus.post(new PluginMessage(SHORTEST_PATH, "getTarget",
			Collections.singletonMap("id", pendingQueryId)));
	}

	/**
	 * True only if the path Shortest Path currently shows is exactly the one we set: a single target
	 * equal to {@link #ourTarget}. Anything else (no target of ours, several targets, a different
	 * point) means the path belongs to someone else.
	 */
	private boolean isOurPath(List<?> targets)
	{
		return ourTarget != null
			&& targets.size() == 1
			&& ourTarget.equals(targets.get(0));
	}

	/**
	 * Points Shortest Path at the given ent, unless the player or another plugin already has a path
	 * of their own. One target, never a set: Shortest Path treats a set as "any of these" and clears
	 * the whole path on reaching any one, dropping the route to every other ent. Asynchronous: the
	 * path is set when Shortest Path's reply arrives, not when this returns.
	 */
	private void pathTo(Ent ent)
	{
		WorldPoint point = new WorldPoint(ent.getCentreX(), ent.getCentreY(), ent.getPlane());

		queryPath(existing ->
		{
			if (existing != null && !isOurPath(existing))
			{
				// Someone else's path, or ours was replaced: leave it alone.
				ourTarget = null;
				return;
			}

			ourTarget = point;
			eventBus.post(new PluginMessage(SHORTEST_PATH, "path",
				Collections.singletonMap("target", point)));
		});
	}

	/**
	 * Clears the path, but only if Shortest Path is still showing the one we set, so a path the
	 * player set afterward is never touched. Asynchronous like {@link #pathTo}. If we have no path
	 * yet, cancels any {@code pathTo} still waiting on its reply so it can't set one after this clear.
	 */
	private void clearPath()
	{
		if (ourTarget == null)
		{
			// Drop any pathTo still waiting on its reply so it can't set a path after we've cleared.
			pendingQuery = null;
			pendingQueryId = null;
			return;
		}

		queryPath(existing ->
		{
			if (existing != null && isOurPath(existing))
			{
				eventBus.post(new PluginMessage(SHORTEST_PATH, "clear", Collections.emptyMap()));
			}
			// Whether or not we cleared, we no longer own a path.
			ourTarget = null;
		});
	}

	/** Point the hint arrow at the first live ent, or take ours down. Client thread. */
	private void updateHintArrow()
	{
		if (live.isEmpty())
		{
			clearHintArrow();
			return;
		}

		// Another source's arrow is not ours to replace.
		if (client.hasHintArrow() && !isOurArrow())
		{
			arrowPoint = null;
			return;
		}

		Ent ent = live.get(0);
		arrowPoint = new WorldPoint(ent.getCentreX(), ent.getCentreY(), ent.getPlane());
		client.setHintArrow(arrowPoint);
	}

	private void clearHintArrow()
	{
		if (isOurArrow())
		{
			client.clearHintArrow();
		}
		arrowPoint = null;
	}

	/** The current hint arrow is still the one we set. */
	private boolean isOurArrow()
	{
		return arrowPoint != null
			&& client.hasHintArrow()
			&& arrowPoint.equals(client.getHintArrowPoint());
	}

	/** Mark the first live ent on the world map, or take the marker down. Client thread. */
	private void updateMapPoint()
	{
		if (live.isEmpty())
		{
			clearMapPoint();
			return;
		}

		Ent ent = live.get(0);
		WorldPoint target = new WorldPoint(ent.getCentreX(), ent.getCentreY(), ent.getPlane());
		if (target.equals(mapTarget))
		{
			return;
		}

		clearMapPoint();
		mapTarget = target;
		mapPoint = WorldMapPoint.builder()
			.worldPoint(target)
			.image(itemManager.getImage(ItemID.BIRD_NEST_EGG_RED))
			.name(ent.getLabel())
			.tooltip(ent.getLabel())
			.snapToEdge(true)
			.jumpOnClick(true)
			.build();
		worldMapPointManager.add(mapPoint);
	}

	private void clearMapPoint()
	{
		if (mapPoint != null)
		{
			worldMapPointManager.remove(mapPoint);
			mapPoint = null;
			mapTarget = null;
		}
	}

	/** Within arrival distance, measured as the game does (Chebyshev). */
	private boolean isReached(Ent ent)
	{
		Player player = client.getLocalPlayer();
		if (player == null)
		{
			return false;
		}
		WorldPoint location = player.getWorldLocation();
		return Math.max(
			Math.abs(location.getX() - ent.getCentreX()),
			Math.abs(location.getY() - ent.getCentreY())) <= ARRIVAL_TILES;
	}

	// ------------------------------------------------------------------ for the overlay

	List<Ent> getLiveEnts()
	{
		return live;
	}

	boolean isRelayOffline()
	{
		return relay.getStatus() == RelayClient.Status.WAITING_TO_RETRY;
	}

	long serverNow()
	{
		return relay.serverNow();
	}
}

package com.scouting.pathfinder;

import com.scouting.ScoutingConfig;
import com.scouting.ScoutingPlugin;
import com.scouting.pathfinder.EntTracker.Ent;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.util.List;
import static net.runelite.api.MenuAction.RUNELITE_OVERLAY;
import static net.runelite.api.MenuAction.RUNELITE_OVERLAY_CONFIG;
import static net.runelite.client.ui.overlay.OverlayManager.OPTION_CONFIGURE;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;

/**
 * Ents not yet reached, oldest first: place on the left, time left on the right. The first line,
 * in white, is where the path points; the rest wait in grey.
 */
class EntPathfinderOverlay extends OverlayPanel
{
	private static final int WIDTH = 210;

	private final EntPathfinder pathfinder;
	private final ScoutingConfig config;

	EntPathfinderOverlay(ScoutingPlugin plugin, EntPathfinder pathfinder, ScoutingConfig config)
	{
		super(plugin);
		this.pathfinder = pathfinder;
		this.config = config;
		setPosition(OverlayPosition.TOP_LEFT);
		panelComponent.setPreferredSize(new Dimension(WIDTH, 0));
		setPriority(PRIORITY_LOW);
		addMenuEntry(RUNELITE_OVERLAY_CONFIG, OPTION_CONFIGURE, "Event Scouting");
	}

	void addSkipEntry(Ent ent)
	{
		addMenuEntry(RUNELITE_OVERLAY, "Skip", ent.getLabel(), e -> pathfinder.skip(ent));
	}

	void removeSkipEntry(Ent ent)
	{
		removeMenuEntry(RUNELITE_OVERLAY, "Skip", ent.getLabel());
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!config.entShowOverlay())
		{
			return null;
		}

		List<Ent> live = pathfinder.getLiveEnts();
		// A debug aid, off by default: to most players a connection line is noise.
		boolean offline = config.warnOnRelayDisconnect() && pathfinder.isRelayOffline();
		if (live.isEmpty() && !offline)
		{
			return null;
		}

		panelComponent.getChildren().add(TitleComponent.builder()
			.text("Event Scouting")
			.color(Color.WHITE)
			.build());

		if (offline)
		{
			panelComponent.getChildren().add(LineComponent.builder()
				.left("Ent relay")
				.leftColor(Color.RED)
				.right("reconnecting")
				.rightColor(Color.GRAY)
				.build());
		}

		long now = pathfinder.serverNow();
		for (Ent ent : live)
		{
			long remaining = ent.secondsRemaining(now);
			panelComponent.getChildren().add(LineComponent.builder()
				.left(ent.getLabel())
				.leftColor(ent == live.get(0) ? Color.WHITE : Color.LIGHT_GRAY)
				.right("(" + remaining + "s)")
				.rightColor(remaining <= 20 ? Color.RED : remaining <= 45 ? Color.ORANGE : Color.GREEN)
				.build());

			if (config.entQuickTele())
			{
				panelComponent.getChildren().add(LineComponent.builder()
					.left(ent.getLocation() != null ? ent.getLocation().getQuickTele() : "See location on world map")
					.leftColor(Color.GRAY)
					.build());
			}
		}

		return super.render(graphics);
	}
}

package com.scouting.pathfinder;

import com.scouting.EventData;
import com.scouting.pathfinder.RelayClient.Call;
import java.util.ArrayList;
import java.util.Collection;
import java.util.Comparator;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import java.util.stream.Collectors;
import lombok.AccessLevel;
import lombok.Getter;
import lombok.Setter;

/**
 * Turns the relay's sightings into distinct ents. One ent arrives as a dozen or more rows -- each
 * scout reports the entling they saw -- scattered over a few tiles and up to a minute apart.
 */
class EntTracker
{

	private final List<Ent> ents = new ArrayList<>();

	/** Feed in a snapshot. Returns the ents seen for the first time that are still running. */
	List<Ent> accept(Collection<Call> calls, long now)
	{
		ents.removeIf(e -> now - e.getFirstSeen() > EventData.EVENT_DEDUPE_DURATION);

		List<Call> ordered = new ArrayList<>(calls);
		ordered.sort(Comparator.comparingLong(Call::getDiscoveredTime));

		List<Ent> started = new ArrayList<>();
		for (Call call : ordered)
		{
			Ent match = ents.stream().filter(e -> e.matches(call)).findFirst().orElse(null);
			if (match != null)
			{
				match.sightings.add(call);
				continue;
			}

			Ent ent = new Ent(call);
			ents.add(ent);
			if (!ent.isExpired(now))
			{
				started.add(ent);
			}
		}
		return started;
	}

	/** Running ents, oldest first: the order they were called and the order they end. */
	List<Ent> getActive(long now)
	{
		return ents.stream()
			.filter(e -> !e.isExpired(now))
			.sorted(Comparator.comparingLong(Ent::getFirstSeen))
			.collect(Collectors.toList());
	}

	void reset()
	{
		ents.clear();
	}

	/** One ent, assembled from every scout's sighting of it. */
	@Getter
	static class Ent
	{
		/** Stated outright on the wiki. */
		private static final int LIFETIME_SECONDS = 120;

		private final int world;
		private final int plane;

		/** The earliest sighting: the best estimate of when the ent spawned. */
		private final long firstSeen;

		/** From the first sighting only, so the name never drifts as more reports move the centre. */
		private final CallLocation location;

		/** Fixed at the first sighting only, so it can key a menu entry. */
		private final String label;

		@Getter(AccessLevel.NONE)
		private final Set<Call> sightings = new HashSet<>();

		/** Kept rather than dropped once reached, or the next snapshot would rebuild it. */
		@Setter(AccessLevel.PACKAGE)
		private boolean reached;

		Ent(Call seed)
		{
			this.world = seed.getWorld();
			this.plane = seed.getPlane();
			this.firstSeen = seed.getDiscoveredTime();
			this.location = CallLocation.nearest(seed.getXCoord(), seed.getYCoord());
			this.label = location == null
				? "Unnamed (" + seed.getXCoord() + ", " + seed.getYCoord() + ")"
				: location.getCallout();
			sightings.add(seed);
		}

		/**
		 * Same world and plane, near the centre, and within the ent's lifetime of its first sighting.
		 * Popular trees spawn repeat ents, so a wider time window would swallow the next one.
		 */
		private boolean matches(Call call)
		{
			return world == call.getWorld()
				&& plane == call.getPlane()
				&& Math.abs(call.getDiscoveredTime() - firstSeen) <= LIFETIME_SECONDS
				&& Math.abs(call.getXCoord() - getCentreX()) <= EventData.EVENT_DEDUPE_DISTANCE
				&& Math.abs(call.getYCoord() - getCentreY()) <= EventData.EVENT_DEDUPE_DISTANCE;
		}

		/** Each sighting is where a scout saw an entling, so the average lands among them. */
		int getCentreX()
		{
			return (int) Math.round(sightings.stream().mapToInt(Call::getXCoord).average().orElse(0));
		}

		int getCentreY()
		{
			return (int) Math.round(sightings.stream().mapToInt(Call::getYCoord).average().orElse(0));
		}

		long secondsRemaining(long now)
		{
			return Math.max(0, LIFETIME_SECONDS - (now - firstSeen));
		}

		boolean isExpired(long now)
		{
			return secondsRemaining(now) <= 0;
		}
	}
}

package com.scouting.pathfinder;

import com.google.gson.Gson;
import com.google.gson.JsonParseException;
import com.google.gson.annotations.SerializedName;
import java.util.Collections;
import java.util.List;
import java.util.Random;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;
import lombok.EqualsAndHashCode;
import lombok.Getter;
import lombok.extern.slf4j.Slf4j;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;
import okhttp3.WebSocket;
import okhttp3.WebSocketListener;

/**
 * Holds one WebSocket to the ent relay, reads the snapshots it pushes, and keeps time with it.
 * Reconnects back off with jitter, so an outage or a relay restart spends few of the relay's
 * 100,000 free connections a day.
 */
@Slf4j
class RelayClient
{
	private static final long FIRST_RETRY_MILLIS = 5_000;
	private static final long MAX_RETRY_MILLIS = 5 * 60_000;

	/** A connection must last this long before a drop resets the backoff. */
	private static final long STABLE_CONNECTION_MILLIS = 60_000;

	/** Protocol-level pings, answered by the relay's runtime without waking it. */
	private static final long PING_INTERVAL_SECONDS = 45;

	/** A relay timestamp further than this from the PC's clock is treated as garbled. */
	private static final long MAX_PLAUSIBLE_SKEW_SECONDS = 24 * 60 * 60;

	private static final int CLOSE_NORMAL = 1000;

	enum Status
	{
		DISCONNECTED,
		CONNECTING,
		CONNECTED,
		WAITING_TO_RETRY
	}

	/** Receives each snapshot on OkHttp's thread. */
	interface Listener
	{
		void onCalls(List<Call> calls);
	}

	private final OkHttpClient httpClient;
	private final Gson gson;
	private final ScheduledExecutorService executor;
	private final Listener listener;
	private final Random random = new Random();

	/** The relay's clock minus the PC's, so ent timers follow the relay. */
	private volatile long clockSkewSeconds;

	// Guarded by "this".
	private String url;
	private WebSocket socket;
	private ScheduledFuture<?> pendingRetry;
	private long connectedAtMillis;
	private int failedAttempts;
	private Status status = Status.DISCONNECTED;
	private boolean closed;

	RelayClient(OkHttpClient httpClient, Gson gson, ScheduledExecutorService executor, Listener listener)
	{
		this.httpClient = httpClient.newBuilder().pingInterval(PING_INTERVAL_SECONDS, TimeUnit.SECONDS).build();
		this.gson = gson;
		this.executor = executor;
		this.listener = listener;
	}

	/** Be connected to {@code url}. Does nothing if already connected or retrying there. */
	synchronized void connect(String url)
	{
		if (closed || (url.equals(this.url) && status != Status.DISCONNECTED))
		{
			return;
		}

		closeCurrent();
		this.url = url;
		failedAttempts = 0;
		open();
	}

	/** Close the connection and stop retrying. A later connect() opens it again. */
	synchronized void disconnect()
	{
		if (status == Status.DISCONNECTED)
		{
			return;
		}

		closeCurrent();
		url = null;
		status = Status.DISCONNECTED;
	}

	/** Disconnect for good, so a connect() still in flight at shutdown cannot reopen it. */
	synchronized void close()
	{
		closed = true;
		disconnect();
	}

	synchronized Status getStatus()
	{
		return status;
	}

	/** Now, in epoch seconds, by the relay's clock. */
	long serverNow()
	{
		return localNowSeconds() + clockSkewSeconds;
	}

	private void open()
	{
		connectedAtMillis = 0;
		status = Status.CONNECTING;
		log.debug("Connecting to ent relay: {}", url);

		try
		{
			socket = httpClient.newWebSocket(new Request.Builder().url(url).build(), new Callbacks());
		}
		catch (IllegalArgumentException e)
		{
			log.warn("Invalid ent relay URL: {}", url);
			socket = null;
			scheduleRetry();
		}
	}

	private void closeCurrent()
	{
		if (pendingRetry != null)
		{
			pendingRetry.cancel(false);
			pendingRetry = null;
		}
		if (socket != null)
		{
			log.debug("Disconnecting from ent relay");
			socket.close(CLOSE_NORMAL, null);
			socket = null;
		}
	}

	private synchronized void handleOpen(WebSocket opened)
	{
		if (opened == socket)
		{
			connectedAtMillis = System.currentTimeMillis();
			status = Status.CONNECTED;
			log.debug("Connected to ent relay");
		}
	}

	private void handleMessage(WebSocket from, String text)
	{
		synchronized (this)
		{
			if (from != socket)
			{
				return;
			}
		}

		// Outside the lock, so a slow listener never holds up connecting or closing.
		RelayMessage message = parseMessage(gson, text);
		if (message != null)
		{
			long localNow = localNowSeconds();
			if (isPlausibleServerTime(message.serverTime, localNow))
			{
				clockSkewSeconds = message.serverTime - localNow;
			}
			listener.onCalls(message.calls);
		}
	}

	/** The connection ended. Reconnect unless it was closed on purpose. */
	private synchronized void handleDrop(WebSocket dropped)
	{
		if (dropped != socket)
		{
			return;
		}
		socket = null;

		if (url == null)
		{
			return;
		}
		// Only a connection that lasted earns a fast reconnect, so a relay that accepts and then
		// immediately drops cannot pull clients into a tight loop.
		if (connectedAtMillis > 0 && System.currentTimeMillis() - connectedAtMillis >= STABLE_CONNECTION_MILLIS)
		{
			failedAttempts = 0;
		}
		scheduleRetry();
	}

	private void scheduleRetry()
	{
		long delay = retryDelayMillis(failedAttempts++, random);
		log.debug("Ent relay connection lost, retrying in {}ms", delay);

		status = Status.WAITING_TO_RETRY;
		pendingRetry = executor.schedule(this::retry, delay, TimeUnit.MILLISECONDS);
	}

	private synchronized void retry()
	{
		pendingRetry = null;
		if (!closed && url != null && socket == null)
		{
			open();
		}
	}

	/** 5s, 10s, 20s... up to five minutes, each randomised to between half and all of that. */
	private static long retryDelayMillis(int attempts, Random random)
	{
		long ceiling = retryCeilingMillis(attempts);
		long floor = ceiling / 2;
		return floor + (long) (random.nextDouble() * (ceiling - floor));
	}

	private static long retryCeilingMillis(int attempts)
	{
		// Capping the shift keeps it far from overflowing a long.
		return Math.min(FIRST_RETRY_MILLIS << Math.min(attempts, 20), MAX_RETRY_MILLIS);
	}

	private static boolean isPlausibleServerTime(long serverTimeSeconds, long localNowSeconds)
	{
		return serverTimeSeconds > 0
			&& Math.abs(serverTimeSeconds - localNowSeconds) <= MAX_PLAUSIBLE_SKEW_SECONDS;
	}

	private static long localNowSeconds()
	{
		return System.currentTimeMillis() / 1000L;
	}

	/** Parse one relay message. Null for anything that is not a well-formed snapshot. */
	private static RelayMessage parseMessage(Gson gson, String text)
	{
		try
		{
			RelayMessage message = gson.fromJson(text, RelayMessage.class);
			if (message == null || !RelayMessage.TYPE_CALLS.equals(message.type))
			{
				return null;
			}
			if (message.calls == null)
			{
				message.calls = Collections.emptyList();
			}
			return message;
		}
		catch (JsonParseException e)
		{
			log.debug("Ignoring malformed ent relay message", e);
			return null;
		}
	}

	/** One push: every current call matching this client's subscription. */
	private static class RelayMessage
	{
		static final String TYPE_CALLS = "calls";

		String type;
		long serverTime;
		List<Call> calls;
	}

	/**
	 * One scout's sighting: where they saw an entling, and when. Field names mirror the scouting API.
	 * Value equality lets an ent ignore a row it already holds, as every push resends them all.
	 */
	@Getter
	@EqualsAndHashCode
	static class Call
	{
		@SerializedName("event_type")
		private String eventType;

		@SerializedName("world")
		private int world;

		@SerializedName("x_coord")
		private int xCoord;

		@SerializedName("y_coord")
		private int yCoord;

		@SerializedName("plane")
		private int plane;

		/** Epoch seconds, from the scout's own clock. */
		@SerializedName("discovered_time")
		private long discoveredTime;
	}

	private class Callbacks extends WebSocketListener
	{
		@Override
		public void onOpen(WebSocket webSocket, Response response)
		{
			handleOpen(webSocket);
		}

		@Override
		public void onMessage(WebSocket webSocket, String text)
		{
			handleMessage(webSocket, text);
		}

		@Override
		public void onClosing(WebSocket webSocket, int code, String reason)
		{
			webSocket.close(CLOSE_NORMAL, null);
		}

		@Override
		public void onClosed(WebSocket webSocket, int code, String reason)
		{
			handleDrop(webSocket);
		}

		@Override
		public void onFailure(WebSocket webSocket, Throwable t, Response response)
		{
			log.debug("Ent relay connection failed", t);
			handleDrop(webSocket);
		}
	}
}

